sets/Art/Characters/ │ │ │ │ ✓ 플랫폼 호환성 │ │ ✓ 메타 파일 존재 확인 │ - Mobile용 에셋 규격 │ │ .meta 파일 누락 감지 │ - Console용 에셋 규격 │ │ │ │ │ ✓ 인코딩/포맷 검증 │ ✓ 런타임 제약 조건 │ │ UTF-8, 특정 압축 포맷 │ - 메모리 예산 범위 내 │ │ │ - 로딩 시간 임계값 │ │ │ │ └───────────────────────────────┴─────────────────────────────────────────────┘ Part 2. 왜 필요해? 수동 검토로는 안 돼? 소규모 프로젝트에서는 수동 검토가 가능하지만, 규모가 커지면 한계 에 부딪힙니다. ┌─────────────────────────────────────────────────────────────────────────────┐ │ 수동 검토 vs 자동 검증 비교 │ ├─────────────────────────────────────────────────────────────────────────────┤ │ │ │ 프로젝트 규모에 따른 검증 비용: │ │ │ │ 비용 │ │ │ ↑ │ ╱ 수동 검토 │ │ │ ╱ (인력 비례 증가) │ │ │ ╱ │ │ │ ╱ │ │ │ ╱ │ │ │ ╱ │ │ │ ╱ │ │ │ ╱ │ │ │ ────────────────────────────────────── 자동 검증 │ │ │ ↑ (초기 구축 후 일정) │ │ │ │ │ │ │ 손익분기점 │ │ │ (약 1만 에셋) │ │ └──────────────────────────────────────────────────▶ 에셋 수 │ │ 1천 5천 1만 5만 10만 │ │ │ ├─────────────────────────────────────────────────────────────────────────────┤ │ 실제 사례: │ │ • AAA 타이틀: 10만+ 에셋 → 수동 검토 불가능 │ │ • 모바일 게임: 1-5만 에셋 → 자동화 ROI 높음 │ │ • 인디 게임: 1천 미만 → 간단한 규칙만 자동화 │ └─────────────────────────────────────────────────────────────────────────────┘ 자동화의 진정한 가치는 일관성 입니다. 사람은 피로, 실수, 주관적 판단이 개입하지만, 자동화된 시스템은 항상 동일한 기준을 적용합니다. 검증 실패 시 어떻게 처리해? 검증 실패 처리 전략은 프로젝트 단계와 규칙의 중요도에 따라 다르게 설정합니다. ┌─────────────────────────────────────────────────────────────────────────────┐ │ 검증 실패 처리 전략 │ ├─────────────────────────────────────────────────────────────────────────────┤ │ │ │ 중요도 레벨별 대응: │ │ │ │ ┌─────────────┬──────────────┬─────────────────────────────────────────┐ │ │ │ Level │ Action │ Description │ │ │ ├─────────────┼──────────────┼─────────────────────────────────────────┤ │ │ │ │ │ │ │ │ │ 🔴 Error │ Block │ Import 거부, 빌드 실패 │ │ │ │ (Critical) │ Import │ 예: 잘못된 포맷, 보안 문제 │ │ │ │ │ │ │ │ │ ├─────────────┼──────────────┼─────────────────────────────────────────┤ │ │ │ │ │ │ │ │ │ 🟠 Warning │ Allow with │ Import 허용, 경고 리포트 생성 │ │ │ │ (Major) │ Report │ 예: 권장 크기 초과, 비표준 네이밍 │ │ │ │ │ │ │ │ │ ├─────────────┼──────────────┼─────────────────────────────────────────┤ │ │ │ │ │ │ │ │ │ 🟡 Info │ Log Only │ 정보만 기록, 통계용 │ │ │ │ (Minor) │ │ 예: 압축률 통계, 사용 빈도 │ │ │ │ │ │ │ │ │ └─────────────┴──────────────┴─────────────────────────────────────────┘ │ │ │ │ 개발 단계별 엄격도 조정: │ │ │ │ 프로토타입 → 알파 → 베타 → 릴리스 │ │ 느슨함 중간 엄격 최고 엄격 │ │ (Warning만) (일부 Block) (대부분 Block) (모든 규칙 강제) │ │ │ └─────────────────────────────────────────────────────────────────────────────┘ Part 3. Unity 구현 Unity에서 어떻게 에셋 검증을 구현해? Unity에서는 AssetPostprocessor 와 EditorWindow 를 조합하여 검증 시스템을 구축합니다. // 네이밍 규칙 검증기 using UnityEditor; using UnityEngine; using System.Text.RegularExpressions; using System.Collections.Generic; public class AssetNamingValidator : AssetPostprocessor { // 에셋 타입별 네이밍 규칙 정의 private static readonly Dictionary string , NamingRule _namingRules = new Dictionary string , NamingRule { // 텍스처: T_[Category]_[Name]_[Suffix] // Suffix: D(Diffuse), N(Normal), M(Metallic), R(Roughness), E(Emissive), O(AO) { ".png" , new NamingRule ( @"^T_[A-Z][a-zA-Z0-9]+_[A-Z][a-zA-Z0-9]+_[DNMREO]$" , "Texture" , "T_Character_Base_D" ) }, { ".tga" , new NamingRule ( @"^T_[A-Z][a-zA-Z0-9]+_[A-Z][a-zA-Z0-9]+_[DNMREO]$" , "Texture" , "T_Environment_Rock_N" ) }, // 메시: SM_[Category]_[Name] (Static), SK_[Category]_[Name] (Skeletal) { ".fbx" , new NamingRule ( @"^(SM|SK)_[A-Z][a-zA-Z0-9]+_[A-Z][a-zA-Z0-9]+$" , "Mesh" , "SM_Props_Chair or SK_Character_Hero" ) }, // 머티리얼: M_[Category]_[Name] { ".mat" , new NamingRule ( @"^M_[A-Z][a-zA-Z0-9]+_[A-Z][a-zA-Z0-9]+$" , "Material" , "M_Character_Skin" ) }, // 프리팹: P_[Category]_[Name] { ".prefab" , new NamingRule ( @"^P_[A-Z][a-zA-Z0-9]+_[A-Z][a-zA-Z0-9]+$" , "Prefab" , "P_UI_HealthBar" ) }, // 애니메이션: A_[Character]_[Action] { ".anim" , new NamingRule ( @"^A_[A-Z][a-zA-Z0-9]+_[A-Z][a-zA-Z0-9]+$" , "Animation" , "A_Hero_Run" ) }, // 오디오: SFX_[Category]_[Name] 또는 BGM_[Name] { ".wav" , new NamingRule ( @"^(SFX|BGM)_[A-Z][a-zA-Z0-9_]+$" , "Audio" , "SFX_UI_Click or BGM_MainMenu" ) }, }; void OnPreprocessAsset () { string ext = System.IO.Path. GetExtension (assetPath).ToLower(); string fileName = System.IO.Path. GetFileNameWithoutExtension (assetPath); if (_namingRules. TryGetValue (ext, out NamingRule rule)) { if (!Regex. IsMatch (fileName, rule.Pattern)) { ValidationResult result = new ValidationResult { AssetPath = assetPath, Rule = "NamingConvention" , Severity = ValidationSeverity .Warning, Message = $"Invalid {rule.AssetType} naming. " + $"Expected pattern: {rule.Example}" }; ValidationReporter . Report (result); } } } } public class NamingRule { public string Pattern { get ; } public string AssetType { get ; } public string Example { get ; } public NamingRule ( string pattern, string assetType, string example) { Pattern = pattern; AssetType = assetType; Example = example; } } 텍스처 크기와 포맷 검증은? 텍스처는 메모리 사용량의 주요 원인이므로 크기, 해상도, 압축 포맷 을 엄격하게 검증해야 합니다. public class TextureValidator : AssetPostprocessor { // 플랫폼별 최대 텍스처 크기 private static readonly Dictionary BuildTarget , int _maxTextureSize = new Dictionary BuildTarget , int { { BuildTarget .iOS, 2048 }, { BuildTarget .Android, 2048 }, { BuildTarget .StandaloneWindows64, 4096 }, { BuildTarget .PS5, 4096 }, }; // 경로별 최대 크기 (UI는 작게, 환경은 크게) private static readonly Dictionary string , int _pathSizeLimits = new Dictionary string , int { { "Assets/Art/UI/" , 512 }, { "Assets/Art/Icons/" , 256 }, { "Assets/Art/Characters/" , 2048 }, { "Assets/Art/Environment/" , 4096 }, }; void OnPreprocessTexture () { TextureImporter importer = ( TextureImporter )assetImporter; List ValidationResult results = new List ValidationResult (); // 1. POT (Power of Two) 검증 ValidatePowerOfTwo (importer, results); // 2. 최대 크기 검증 ValidateMaxSize (importer, results); // 3. 압축 포맷 검증 ValidateCompression (importer, results); // 4. 밉맵 설정 검증 ValidateMipMaps (importer, results); // 5. Read/Write 설정 검증 ValidateReadWrite (importer, results); foreach ( var result in results) { ValidationReporter . Report (result); } } private void ValidatePowerOfTwo ( TextureImporter importer, List ValidationResult results) { // UI 스프라이트는 POT 불필요 if (importer.textureType == TextureImporterType .Sprite) return ; // 원본 텍스처 크기 확인 (에디터 API 사용) int width, height; if (! GetOriginalTextureSize (assetPath, out width, out height)) return ; if (! IsPowerOfTwo (width) || ! IsPowerOfTwo (height)) { results. Add ( new ValidationResult { AssetPath = assetPath, Rule = "PowerOfTwo" , Severity = ValidationSeverity .Warning, Message = $"Texture size ({width}x{height}) is not power of two. " + "This may cause compression issues on mobile." }); } } private void ValidateCompression ( TextureImporter importer, List ValidationResult results) { // Android 설정 확인 TextureImporterPlatformSettings androidSettings = importer. GetPlatformTextureSettings ( "Android" ); if (androidSettings.overridden) { // ASTC 권장 (최신 기기), ETC2 허용 (호환성) var format = androidSettings.format; bool isAcceptable = format == TextureImporterFormat .ASTC_6x6 || format == TextureImporterFormat .ASTC_8x8 || format == TextureImporterFormat .ETC2_RGBA8; if (!isAcceptable) { results. Add ( new ValidationResult { AssetPath = assetPath, Rule = "AndroidCompression" , Severity = ValidationSeverity .Warning, Message = $"Android texture format {format} is not recommended. " + "Use ASTC_6x6/8x8 or ETC2_RGBA8." }); } } else { results. Add ( new ValidationResult { AssetPath = assetPath, Rule = "PlatformOverride" , Severity = ValidationSeverity .Info, Message = "No Android-specific texture settings. Consider adding platform override." }); } } private void ValidateReadWrite ( TextureImporter importer, List ValidationResult results) { // Read/Write 활성화 = 메모리 2배 사용 if (importer.isReadable) { results. Add ( new ValidationResult { AssetPath = assetPath, Rule = "ReadWriteEnabled" , Severity = ValidationSeverity .Warning, Message = "Read/Write enabled doubles memory usage. " + "Disable unless runtime pixel access is needed." }); } } private bool IsPowerOfTwo ( int value) { return value > 0 && (value & (value - 1 )) == 0 ; } private bool GetOriginalTextureSize ( string path, out int width, out int height) { // 실제 이미지 파일 크기 읽기 try { byte [] data = System.IO.File. ReadAllBytes (path); Texture2D temp = new Texture2D ( 1 , 1 ); temp. LoadImage (data); width = temp.width; height = temp.height; Object . DestroyImmediate (temp); return true ; } catch { width = height = 0 ; return false ; } } } 메시 폴리곤 수 검증은 어떻게 해? 메시 폴리곤 수는 렌더링 성능에 직접 영향을 미칩니다. LOD 레벨별, 용도별 로 다른 기준을 적용합니다. public class MeshValidator : AssetPostprocessor { // 메시 카테고리별 폴리곤 제한 private static readonly Dictionary string , MeshLimits _meshLimits = new Dictionary string , MeshLimits { // 메인 캐릭터 (높은 품질) { "Characters/Hero" , new MeshLimits ( 30000 , 15000 , 5000 , 1000 ) }, // NPC/몬스터 (중간 품질) { "Characters/NPC" , new MeshLimits ( 15000 , 7500 , 3000 , 500 ) }, // 환경 오브젝트 (다양) { "Environment/Props" , new MeshLimits ( 5000 , 2500 , 1000 , 200 ) }, // 배경 건물 { "Environment/Buildings" , new MeshLimits ( 50000 , 20000 , 5000 , 1000 ) }, // 무기/장비 { "Items/Weapons" , new MeshLimits ( 8000 , 4000 , 1500 , 300 ) }, }; void OnPostprocessModel ( GameObject model) { MeshFilter [] meshFilters = model. GetComponentsInChildren MeshFilter (); SkinnedMeshRenderer [] skinnedMeshes = model. GetComponentsInChildren SkinnedMeshRenderer (); int totalVertices = 0 ; int totalTriangles = 0 ; // 정적 메시 합산 foreach ( var mf in meshFilters) { if (mf.sharedMesh != null ) { totalVertices += mf.sharedMesh.vertexCount; totalTriangles += mf.sharedMesh.triangles.Length / 3 ; } } // 스킨드 메시 합산 foreach ( var smr in skinnedMeshes) { if (smr.sharedMesh != null ) { totalVertices += smr.sharedMesh.vertexCount; totalTriangles += smr.sharedMesh.triangles.Length / 3 ; } } // 카테고리 판별 MeshLimits limits = GetLimitsForPath (assetPath); if (totalTriangles > limits.LOD0Max) { ValidationReporter . Report ( new ValidationResult { AssetPath = assetPath, Rule = "MeshPolygonCount" , Severity = ValidationSeverity .Error, Message = $"Mesh has {totalTriangles:N0} triangles. " + $"Maximum allowed for this category: {limits.LOD0Max:N0}" }); } // LOD 존재 여부 확인 LODGroup lodGroup = model. GetComponent LODGroup (); if (lodGroup == null && totalTriangles > 3000 ) { ValidationReporter . Report ( new ValidationResult { AssetPath = assetPath, Rule = "MissingLOD" , Severity = ValidationSeverity .Warning, Message = $"High-poly mesh ({totalTriangles:N0} tris) without LOD. " + "Consider adding LOD levels for performance." }); } // 본 개수 검증 (모바일 제한) if (skinnedMeshes.Length > 0 ) { int maxBones = skinnedMeshes. Max (smr => smr.sharedMesh?.bindposes?.Length ?? 0 ); if (maxBones > 75 ) // 모바일 권장 최대 { ValidationReporter . Report ( new ValidationResult { AssetPath = assetPath, Rule = "BoneCount" , Severity = ValidationSeverity .Warning, Message = $"Skinned mesh has {maxBones} bones. " + "Mobile recommends ≤75 bones per mesh." }); } } } private MeshLimits GetLimitsForPath ( string path) { foreach ( var kvp in _meshLimits) { if (path. Contains (kvp.Key)) return kvp.Value; } // 기본 제한 return new MeshLimits ( 10000 , 5000 , 2000 , 500 ); } } public struct MeshLimits { public int LOD0Max; // 가장 높은 품질 public int LOD1Max; // 중간 거리 public int LOD2Max; // 먼 거리 public int LOD3Max; // 가장 먼 거리 public MeshLimits ( int lod0, int lod1, int lod2, int lod3) { LOD0Max = lod0; LOD1Max = lod1; LOD2Max = lod2; LOD3Max = lod3; } } Part 4. 통합 검증 시스템 모든 검증을 통합 관리하는 시스템은? 개별 검증기를 중앙 집중식 리포터 로 통합하면 일관된 결과 수집과 리포팅이 가능합니다. using System; using System.Collections.Generic; using System.IO; using UnityEditor; using UnityEngine; public enum ValidationSeverity { Info, // 정보성 - 로그만 Warning, // 경고 - 리포트 생성 Error // 에러 - Import 차단 가능 } public class ValidationResult { public string AssetPath { get ; set ; } public string Rule { get ; set ; } public ValidationSeverity Severity { get ; set ; } public string Message { get ; set ; } public DateTime Timestamp { get ; set ; } = DateTime .Now; public string ToLogString () { return $"[{Severity}] {Rule}: {AssetPath}
 {Message}" ; } public string ToCsvLine () { return $""{Timestamp:yyyy-MM-dd HH:mm:ss}","{Severity}","{Rule}","{AssetPath}","{Message}"" ; } } public static class ValidationReporter { private static List ValidationResult _sessionResults = new List ValidationResult (); private static readonly string ReportPath = "Assets/Editor/ValidationReports/" ; // 검증 설정 public static bool BlockOnError { get ; set ; } = false ; public static bool LogToConsole { get ; set ; } = true ; public static bool AutoExportReport { get ; set ; } = true ; public static void Report ( ValidationResult result) { _sessionResults. Add (result); if (LogToConsole) { switch (result.Severity) { case ValidationSeverity .Info: Debug. Log (result. ToLogString ()); break ; case ValidationSeverity .Warning: Debug. LogWarning (result. ToLogString ()); break ; case ValidationSeverity .Error: Debug. LogError (result. ToLogString ()); break ; } } // Error 레벨에서 Import 차단 if (BlockOnError && result.Severity == ValidationSeverity .Error) { throw new Exception ( $"Asset validation failed: {result.Message}" ); } } // 세션 종료 시 리포트 생성 [ InitializeOnLoadMethod ] static void RegisterSessionEnd () { EditorApplication .quitting += ExportSessionReport ; AssemblyReloadEvents .beforeAssemblyReload += ExportSessionReport ; } public static void ExportSessionReport () { if (!AutoExportReport || _sessionResults.Count == 0 ) return ; if (! Directory . Exists (ReportPath)) Directory . CreateDirectory (ReportPath); string fileName = $"validation_{DateTime.Now:yyyyMMdd_HHmmss}.csv" ; string fullPath = ReportPath + fileName; using ( StreamWriter writer = new StreamWriter (fullPath)) { writer. WriteLine ( "Timestamp,Severity,Rule,AssetPath,Message" ); foreach ( var result in _sessionResults) { writer. WriteLine (result. ToCsvLine ()); } } Debug. Log ( $"Validation report exported: {fullPath}" ); _sessionResults. Clear (); } // 수동으로 전체 프로젝트 검증 [ MenuItem ( "Tools/Validation/Run Full Project Validation" )] public static void RunFullValidation () { _sessionResults. Clear (); string [] allAssets = AssetDatabase . GetAllAssetPaths (); int processed = 0 ; foreach ( string assetPath in allAssets) { if (assetPath. StartsWith ( "Assets/" )) { // 강제 재임포트로 검증 트리거 AssetDatabase . ImportAsset (assetPath, ImportAssetOptions .ForceUpdate); processed++; if (processed % 100 == 0 ) { EditorUtility . DisplayProgressBar ( "Validating Assets" , $"Processing {processed}/{allAssets.Length}" , ( float )processed / allAssets.Length); } } } EditorUtility . ClearProgressBar (); ExportSessionReport (); Debug. Log ( $"Validation complete. {_sessionResults.Count} issues found." ); } // 통계 요약 [ MenuItem ( "Tools/Validation/Show Session Summary" )] public static void ShowSummary () { var byRule = _sessionResults. GroupBy (r => r.Rule); var bySeverity = _sessionResults. GroupBy (r => r.Severity); string summary = "=== Validation Summary ===

" ; summary += "By Severity:
" ; foreach ( var group in bySeverity) { summary += $" {group.Key}: {group.Count()}
" ; } summary += "
By Rule:
" ; foreach ( var group in byRule. OrderByDescending (g => g. Count ())) { summary += $" {group.Key}: {group.Count()}
" ; } Debug. Log (summary); } } 에디터 윈도우로 검증 결과를 시각화하고 싶어 커스텀 EditorWindow 를 만들면 검증 결과를 한눈에 파악하고 문제 에셋으로 바로 이동할 수 있습니다. using UnityEditor; using UnityEngine; using System.Collections.Generic; using System.Linq; public class ValidationDashboard : EditorWindow { private Vector2 _scrollPosition; private List ValidationResult _results = new List ValidationResult (); private string _filterRule = "" ; private ValidationSeverity ? _filterSeverity = null ; private GUIStyle _errorStyle; private GUIStyle _warningStyle; private GUIStyle _infoStyle; [ MenuItem ( "Tools/Validation/Dashboard" )] public static void ShowWindow () { GetWindow ValidationDashboard ( "Asset Validation" ); } private void OnEnable () { RefreshResults (); } private void InitStyles () { if (_errorStyle == null ) { _errorStyle = new GUIStyle ( EditorStyles .label); _errorStyle.normal.textColor = new Color ( 0.9f , 0.3f , 0.3f ); _warningStyle = new GUIStyle ( EditorStyles .label); _warningStyle.normal.textColor = new Color ( 0.9f , 0.7f , 0.2f ); _infoStyle = new GUIStyle ( EditorStyles .label); _infoStyle.normal.textColor = new Color ( 0.5f , 0.7f , 0.9f ); } } private void OnGUI () { InitStyles (); // 헤더 영역 EditorGUILayout . BeginHorizontal ( EditorStyles .toolbar); { if ( GUILayout . Button ( "Refresh" , EditorStyles .toolbarButton)) { RefreshResults (); } if ( GUILayout . Button ( "Run Full Scan" , EditorStyles .toolbarButton)) { ValidationReporter . RunFullValidation (); RefreshResults (); } if ( GUILayout . Button ( "Export CSV" , EditorStyles .toolbarButton)) { ValidationReporter . ExportSessionReport (); } GUILayout . FlexibleSpace (); // 필터 EditorGUILayout . LabelField ( "Filter:" , GUILayout . Width ( 40 )); _filterRule = EditorGUILayout . TextField (_filterRule, EditorStyles .toolbarSearchField, GUILayout . Width ( 150 )); } EditorGUILayout . EndHorizontal (); // 요약 통계 DrawSummaryBar (); // 결과 목록 _scrollPosition = EditorGUILayout . BeginScrollView (_scrollPosition); { var filtered = GetFilteredResults (); foreach ( var result in filtered) { DrawResultItem (result); } if (filtered.Count == 0 ) { EditorGUILayout . HelpBox ( "No validation issues found. Great job!" , MessageType .Info); } } EditorGUILayout . EndScrollView (); } private void DrawSummaryBar () { int errors = _results. Count (r => r.Severity == ValidationSeverity .Error); int warnings = _results. Count (r => r.Severity == ValidationSeverity .Warning); int infos = _results. Count (r => r.Severity == ValidationSeverity .Info); EditorGUILayout . BeginHorizontal ( EditorStyles .helpBox); { // 클릭하면 해당 레벨로 필터 GUI .color = new Color ( 0.9f , 0.3f , 0.3f ); if ( GUILayout . Button ( $"❌ Errors: {errors}" , EditorStyles .miniButton)) _filterSeverity = ValidationSeverity .Error; GUI .color = new Color ( 0.9f , 0.7f , 0.2f ); if ( GUILayout . Button ( $"⚠️ Warnings: {warnings}" , EditorStyles .miniButton)) _filterSeverity = ValidationSeverity .Warning; GUI .color = new Color ( 0.5f , 0.7f , 0.9f ); if ( GUILayout . Button ( $"ℹ️ Info: {infos}" , EditorStyles .miniButton)) _filterSeverity = ValidationSeverity .Info; GUI .color = Color .white; if ( GUILayout . Button ( "Clear Filter" , EditorStyles .miniButton)) { _filterSeverity = null ; _filterRule = "" ; } } EditorGUILayout . EndHorizontal (); } private void DrawResultItem ( ValidationResult result) { GUIStyle style = result.Severity switch { ValidationSeverity .Error => _errorStyle, ValidationSeverity .Warning => _warningStyle, _ => _infoStyle }; EditorGUILayout . BeginHorizontal ( EditorStyles .helpBox); { // 아이콘 string icon = result.Severity switch { ValidationSeverity .Error => "❌" , ValidationSeverity .Warning => "⚠️" , _ => "ℹ️" }; EditorGUILayout . LabelField (icon, GUILayout . Width ( 25 )); // 규칙 EditorGUILayout . LabelField (result.Rule, style, GUILayout . Width ( 150 )); // 메시지 EditorGUILayout . LabelField (result.Message, GUILayout . ExpandWidth ( true )); // 에셋으로 이동 버튼 if ( GUILayout . Button ( "Select" , GUILayout . Width ( 50 ))) { Object asset = AssetDatabase . LoadAssetAtPath Object (result.AssetPath); if (asset != null ) { Selection .activeObject = asset; EditorGUIUtility . PingObject (asset); } } } EditorGUILayout . EndHorizontal (); } private List ValidationResult GetFilteredResults () { var filtered = _results. AsEnumerable (); if (_filterSeverity. HasValue ) filtered = filtered. Where (r => r.Severity == _filterSeverity.Value); if (! string . IsNullOrEmpty (_filterRule)) filtered = filtered. Where (r => r.Rule. Contains (_filterRule, StringComparison .OrdinalIgnoreCase) || r.AssetPath. Contains (_filterRule, StringComparison .OrdinalIgnoreCase)); return filtered. ToList (); } private void RefreshResults () { // ValidationReporter에서 결과 가져오기 (실제 구현에서는 공유 상태 사용) _results = new List ValidationResult (); Repaint (); } } Part 5. CI/CD 통합 CI/CD 파이프라인에서 검증을 어떻게 돌려? Unity의 배치 모드 를 활용하면 CI 환경에서 헤드리스(headless)로 검증을 실행할 수 있습니다. ┌─────────────────────────────────────────────────────────────────────────────┐ │ CI/CD 검증 파이프라인 │ ├─────────────────────────────────────────────────────────────────────────────┤ │ │ │ [Git Push / PR] │ │ │ │ │ ▼ │ │ ┌─────────────────────────────────────────────────────────────────────┐ │ │ │ CI Server (Jenkins/GitHub Actions) │ │ │ │ │ │ │ │ Stage 1: Asset Validation │ │ │ │ ┌─────────────────────────────────────────────────────────────┐ │ │ │ │ │ Unity -batchmode -executeMethod ValidationRunner.Run │ │ │ │ │ │ │ │ │ │ │ │ → Naming Check │ │ │ │ │ │ → Size Check │ │ │ │ │ │ → Format Check │ │ │ │ │ │ → Reference Check │ │ │ │ │ │ │ │ │ │ │ │ Output: validation_report.json │ │ │ │ │ └─────────────────────────────────────────────────────────────┘ │ │ │ │ │ │ │ │ │ ▼ │ │ │ │ ┌────────┐ │ │ │ │ │ Pass? │─── No ──▶ ❌ Pipeline Failed (Block Merge) │ │ │ │ └────┬───┘ │ │ │ │ │ Yes │ │ │ │ ▼ │ │ │ │ Stage 2: Build │ │ │ │ ┌─────────────────────────────────────────────────────────────┐ │ │ │ │ │ Unity -batchmode -buildTarget Android -executeMethod Build │ │ │ │ │ └─────────────────────────────────────────────────────────────┘ │ │ │ │ │ │ │ │ │ ▼ │ │ │ │ Stage 3: Test (Optional) │ │ │ │ ┌─────────────────────────────────────────────────────────────┐ │ │ │ │ │ Unity -runTests -testPlatform PlayMode │ │ │ │ │ └─────────────────────────────────────────────────────────────┘ │ │ │ │ │ │ │ │ │ ▼ │ │ │ │ ✅ Pipeline Success → Merge Allowed │ │ │ │ │ │ │ └─────────────────────────────────────────────────────────────────────┘ │ │ │ └─────────────────────────────────────────────────────────────────────────────┘ // CI용 배치 모드 검증 러너 using UnityEditor; using UnityEngine; using System; using System.IO; using System.Collections.Generic; public static class CIValidationRunner { private const string OutputPath = "./validation_report.json" ; // CI에서 호출: Unity -batchmode -executeMethod CIValidationRunner.Run public static void Run () { Debug. Log ( "=== Starting CI Asset Validation ===" ); List ValidationResult allResults = new List ValidationResult (); bool hasErrors = false ; try { // 1. 모든 에셋 수집 string [] assetPaths = AssetDatabase . GetAllAssetPaths (); int totalAssets = assetPaths.Length; int processed = 0 ; foreach ( string path in assetPaths) { if (!path. StartsWith ( "Assets/" )) continue ; // 각 에셋 검증 var results = ValidateAsset (path); allResults. AddRange (results); if (results. Any (r => r.Severity == ValidationSeverity .Error)) hasErrors = true ; processed++; if (processed % 500 == 0 ) Debug. Log ( $"Progress: {processed}/{totalAssets}" ); } // 2. 리포트 생성 GenerateReport (allResults); // 3. 요약 출력 int errors = allResults. Count (r => r.Severity == ValidationSeverity .Error); int warnings = allResults. Count (r => r.Severity == ValidationSeverity .Warning); Debug. Log ( $"
=== Validation Complete ===" ); Debug. Log ( $"Total Assets: {totalAssets}" ); Debug. Log ( $"Errors: {errors}" ); Debug. Log ( $"Warnings: {warnings}" ); Debug. Log ( $"Report: {OutputPath}" ); // 4. 에러가 있으면 실패 코드로 종료 if (hasErrors) { Debug. LogError ( "Validation FAILED - Errors found" ); EditorApplication . Exit ( 1 ); } else { Debug. Log ( "Validation PASSED" ); EditorApplication . Exit ( 0 ); } } catch ( Exception ex) { Debug. LogError ( $"Validation crashed: {ex}" ); EditorApplication . Exit ( 2 ); } } private static List ValidationResult ValidateAsset ( string path) { var results = new List ValidationResult (); // 확장자별 검증 로직 분기 string ext = Path. GetExtension (path).ToLower(); switch (ext) { case ".png" : case ".tga" : case ".jpg" : results. AddRange ( TextureValidationRules . Validate (path)); break ; case ".fbx" : case ".obj" : results. AddRange ( MeshValidationRules . Validate (path)); break ; case ".prefab" : results. AddRange ( PrefabValidationRules . Validate (path)); break ; } // 공통 규칙 (네이밍) results. AddRange ( NamingValidationRules . Validate (path)); return results; } private static void GenerateReport ( List ValidationResult results) { var report = new { timestamp = DateTime .UtcNow. ToString ( "o" ), summary = new { total = results.Count, errors = results. Count (r => r.Severity == ValidationSeverity .Error), warnings = results. Count (r => r.Severity == ValidationSeverity .Warning), info = results. Count (r => r.Severity == ValidationSeverity .Info) }, issues = results. Select (r => new { severity = r.Severity. ToString (), rule = r.Rule, path = r.AssetPath, message = r.Message }) }; string json = JsonUtility . ToJson (report, true ); File. WriteAllText (OutputPath, json); } } GitHub Actions 예시: # .github/workflows/asset-validation.yml name: Asset Validation on: pull_request: paths: - 'Assets/**' jobs: validate: runs-on: ubuntu-latest steps: - uses: actions/checkout@v3 with: lfs: true - name: Cache Unity Library uses: actions/cache@v3 with: path: Library key: Library-${{ hashFiles('Assets/**', 'Packages/**') }} - name: Run Asset Validation uses: game-ci/unity-builder@v2 env: UNITY_LICENSE: ${{ secrets.UNITY_LICENSE }} with: targetPlatform: StandaloneLinux64 buildMethod: CIValidationRunner.Run - name: Upload Validation Report uses: actions/upload-artifact@v3 if: always() with: name: validation-report path: validation_report.json - name: Comment PR with Results uses: actions/github-script@v6 if: failure() with: script: | const fs = require('fs'); const report = JSON.parse(fs.readFileSync('validation_report.json')); let body = '## ❌ Asset Validation Failed

'; body += `| Metric | Count |
|--------|-------|
`; body += `| Errors | ${report.summary.errors} |
`; body += `| Warnings | ${report.summary.warnings} |
`; body += '
### Top Issues:
'; report.issues .filter(i => i.severity === 'Error') .slice(0, 10) .forEach(i => { body += `- **${i.rule}**: ${i.path}
`; }); github.rest.issues.createComment({ issue_number: context.issue.number, owner: context.repo.owner, repo: context.repo.repo, body: body }); Part 6. 실전 규칙 템플릿 프로젝트에 바로 적용할 수 있는 규칙 템플릿이 있어? 일반적인 모바일 게임 프로젝트에 적합한 검증 규칙 템플릿 입니다. 프로젝트 특성에 맞게 수정하세요. // ValidationRulesConfig.cs - ScriptableObject로 규칙 관리 using UnityEngine; using System; using System.Collections.Generic; [ CreateAssetMenu (fileName = "ValidationRules" , menuName = "Config/Validation Rules" )] public class ValidationRulesConfig : ScriptableObject { [ Header ( "=== Texture Rules ===" )] public TextureRules textureRules = new TextureRules (); [ Header ( "=== Mesh Rules ===" )] public MeshRules meshRules = new MeshRules (); [ Header ( "=== Audio Rules ===" )] public AudioRules audioRules = new AudioRules (); [ Header ( "=== Naming Rules ===" )] public NamingRules namingRules = new NamingRules (); [ Header ( "=== Global Settings ===" )] public bool blockOnError = false ; public bool strictModeInCI = true ; } [ Serializable ] public class TextureRules { [ Header ( "Size Limits" )] public int maxSizeMobile = 2048 ; public int maxSizePC = 4096 ; public int maxSizeUI = 512 ; public int maxSizeIcon = 256 ; [ Header ( "Format Requirements" )] public bool requirePowerOfTwo = true ; public bool disallowReadWrite = true ; public bool requireMipMaps = true ; [ Header ( "Compression" )] public TextureImporterFormat [] allowedAndroidFormats = { TextureImporterFormat .ASTC_6x6, TextureImporterFormat .ASTC_8x8, TextureImporterFormat .ETC2_RGBA8 }; public TextureImporterFormat [] allowedIOSFormats = { TextureImporterFormat .ASTC_6x6, TextureImporterFormat .ASTC_8x8, TextureImporterFormat .PVRTC_RGBA4 }; } [ Serializable ] public class MeshRules { [ Header ( "Polygon Limits" )] public int maxTrianglesHero = 30000 ; public int maxTrianglesNPC = 15000 ; public int maxTrianglesProp = 5000 ; public int maxTrianglesEnvironment = 50000 ; [ Header ( "Skinned Mesh" )] public int maxBonesPerMesh = 75 ; public int maxBonesPerVertex = 4 ; [ Header ( "LOD Requirements" )] public int lodRequiredAboveTriangles = 3000 ; public int minLODLevels = 3 ; } [ Serializable ] public class AudioRules { [ Header ( "Sample Rate" )] public int maxSampleRateSFX = 44100 ; public int maxSampleRateBGM = 48000 ; public int maxSampleRateVoice = 22050 ; [ Header ( "Channels" )] public bool forceMono = false ; public bool allowStereoForBGM = true ; [ Header ( "File Size" )] public long maxFileSizeSFX = 500 * 1024 ; // 500KB public long maxFileSizeBGM = 10 * 1024 * 1024 ; // 10MB [ Header ( "Compression" )] public bool requireCompression = true ; } [ Serializable ] public class NamingRules { [ Header ( "Prefix Rules" )] public List PrefixRule prefixRules = new List PrefixRule { new PrefixRule { extension = ".png" , prefix = "T_" , assetType = "Texture" }, new PrefixRule { extension = ".tga" , prefix = "T_" , assetType = "Texture" }, new PrefixRule { extension = ".mat" , prefix = "M_" , assetType = "Material" }, new PrefixRule { extension = ".prefab" , prefix = "P_" , assetType = "Prefab" }, new PrefixRule { extension = ".anim" , prefix = "A_" , assetType = "Animation" }, new PrefixRule { extension = ".wav" , prefix = "SFX_|BGM_" , assetType = "Audio" }, }; [ Header ( "General" )] public bool disallowSpaces = true ; public bool disallowSpecialChars = true ; public bool disallowKorean = true ; public int maxFileNameLength = 64 ; } [ Serializable ] public class PrefixRule { public string extension; public string prefix; // | 로 복수 허용 public string assetType; } 흔히 발생하는 검증 실패 케이스와 해결 방법은? 자주 발생하는 검증 실패 패턴과 그 해결책입니다. ┌─────────────────────────────────────────────────────────────────────────────┐ │ 자주 발생하는 검증 실패 케이스 │ ├─────────────────────────────────────────────────────────────────────────────┤ │ │ │ ❌ Case 1: 텍스처 크기 초과 │ │ ├─ 원인: 4K 원본 그대로 Import │ │ ├─ 영향: 메모리 폭발, 모바일 크래시 │ │ └─ 해결: Max Size 설정 + 플랫폼별 Override │ │ │ │ ❌ Case 2: Read/Write 활성화 │ │ ├─ 원인: 런타임 텍스처 수정 의도 없이 켜둠 │ │ ├─ 영향: 메모리 2배 사용 │ │ └─ 해결: 기본 비활성화, 필요한 에셋만 명시적 활성화 │ │ │ │ ❌ Case 3: 누락된 메타 파일 │ │ ├─ 원인: .gitignore 설정 오류, 수동 파일 복사 │ │ ├─ 영향: Import 설정 손실, 팀원 간 불일치 │ │ └─ 해결: Visible Meta Files 모드 + 메타 검증 추가 │ │ │ │ ❌ Case 4: 순환 참조 (Circular Reference) │ │ ├─ 원인: Prefab A → Prefab B → Prefab A │ │ ├─ 영향: 무한 로딩, 스택 오버플로우 │ │ └─ 해결: 의존성 그래프 분석 + 참조 검증 │ │ │ │ ❌ Case 5: 외부 경로 참조 │ │ ├─ 원인: 절대 경로 또는 Assets 외부 참조 │ │ ├─ 영향: 빌드 실패, 다른 PC에서 에러 │ │ └─ 해결: 경로 검증 + Assets 내부만 허용 │ │ │ │ ❌ Case 6: 비표준 인코딩 │ │ ├─ 원인: 스크립트에 BOM 없는 UTF-8, 또는 다른 인코딩 │ │ ├─ 영향: 컴파일 에러, 문자 깨짐 │ │ └─ 해결: UTF-8 with BOM 강제 + 인코딩 검증 │ │ │ └─────────────────────────────────────────────────────────────────────────────┘ Part 7. 핵심 정리 에셋 검증 자동화의 핵심만 정리해줘 ┌─────────────────────────────────────────────────────────────────────────────┐ │ 에셋 검증 자동화 핵심 정리 │ ├─────────────────────────────────────────────────────────────────────────────┤ │ │ │ 📌 검증 타이밍 │ │ ├─ Import Time: AssetPostprocessor (즉시 피드백) │ │ ├─ Pre-Build: BuildPlayerProcessor (빌드 전 체크) │ │ └─ CI/CD: Batch Mode 스크립트 (PR 병합 전 검증) │ │ │ │ 📌 검증 레벨 │ │ ├─ 🔴 Error: Import 차단, 빌드 실패 │ │ ├─ 🟠 Warning: 리포트 생성, 수정 권고 │ │ └─ 🟡 Info: 로깅만, 통계 수집용 │ │ │ │ 📌 필수 검증 항목 │ │ ├─ 네이밍 규칙: 일관된 파일명 → 검색성, 자동화 용이 │ │ ├─ 크기 제한: 텍스처/메시/오디오 → 메모리 관리 │ │ ├─ 포맷 검증: 플랫폼별 최적화 → 성능 │ │ └─ 참조 무결성: 누락 참조, 순환 참조 → 런타임 안정성 │ │ │ │ 📌 구현 핵심 │ │ ├─ ScriptableObject로 규칙 관리 (하드코딩 X) │ │ ├─ 중앙 집중식 Reporter (일관된 출력) │ │ ├─ Dashboard UI (시각적 확인 + 빠른 이동) │ │ └─ CI 통합 (자동 검증 + PR 코멘트) │ │ │ │ 📌 팀 도입 전략 │ │ ├─ Phase 1: Warning만 (적응 기간) │ │ ├─ Phase 2: 신규 에셋에 Error 적용 │ │ ├─ Phase 3: 기존 에셋 정리 + 전체 Error 적용 │ │ └─ Phase 4: CI 필수 통과 조건화 │ │ │ │ 💡 핵심 원칙 │ │ "Early Detection, Fast Feedback" │ │ 문제는 Import 시점에 잡아야 수정 비용이 최소화된다 │ │ │ └─────────────────────────────────────────────────────────────────────────────┘ 핵심 요약 AssetPostprocessor 로 Import 시점에 즉시 검증 네이밍/크기/포맷 규칙을 ScriptableObject로 관리 ValidationReporter 로 중앙 집중식 결과 수집 EditorWindow 로 시각적 대시보드 제공 CI/CD 에서 배치 모드로 자동 검증 실행 개발 단계에 따라 엄격도 점진적 강화 에셋 프로세서 빌드 시간 단축 전략

