클릭 5. 키 복사해서 안전한 곳에 저장! ⚠️ 키는 절대 공개 저장소에 올리지 마! 2 Unity 코드 // NPCDialogueManager.cs using UnityEngine; using UnityEngine.Networking; using System.Collections; public class NPCDialogueManager : MonoBehaviour { [SerializeField] private string apiKey = "sk-..." ; [SerializeField] private string systemPrompt; public IEnumerator SendMessage( string input, System.Action string onResponse) { string json = $@"{{ ""model"": ""gpt-4o-mini"", ""messages"": [ {{""role"": ""system"", ""content"": ""{systemPrompt}""}}, {{""role"": ""user"", ""content"": ""{input}""}} ], ""max_tokens"": 150 }}" ; using (UnityWebRequest req = new UnityWebRequest( "https://api.openai.com/v1/chat/completions" , "POST" )) { req.uploadHandler = new UploadHandlerRaw( System.Text.Encoding.UTF8.GetBytes(json)); req.downloadHandler = new DownloadHandlerBuffer(); req.SetRequestHeader( "Content-Type" , "application/json" ); req.SetRequestHeader( "Authorization" , $"Bearer {apiKey}" ); yield return req.SendWebRequest(); if (req.result == UnityWebRequest.Result.Success) { // JSON 파싱 후 응답 반환 onResponse?.Invoke(ParseResponse(req.downloadHandler.text)); } } } } 예상 비용 테스트용: 월 $5 이하 gpt-4o-mini는 100만 토큰당 약 $0.15! Part 5. Ollama + Unity (무료!) 무료로 하고 싶은데? Ollama = 내 컴퓨터에서 LLM 실행! API 비용 0원, 인터넷 없이도 가능. 1 Ollama 설치 # Windows (PowerShell) winget install Ollama.Ollama # Mac brew install ollama # 모델 다운로드 (약 4GB) ollama pull llama3.1:8b # 서버 실행 ollama serve → http://localhost:11434 에서 동작! 2 Unity 코드 // OllamaManager.cs private const string OLLAMA_URL = "http://localhost:11434/api/generate" ; public IEnumerator SendMessage( string prompt, System.Action string onResponse) { string fullPrompt = $"[시스템]
{systemPrompt}

[유저]
